INSERT INTO `creature_text` (`entry`, `groupid`, `id`, `text`, `type`, `language`, `probability`, `emote`, `duration`, `sound`, `comment`) VALUES
(25396, 0, 0, 'You cannot stop us all!', 12, 0, 100, 0, 0, 0, 'Naxxanar Skeletal Mage'),
(25396, 0, 1, 'Your death will soon follow....', 12, 0, 100, 0, 0, 0, 'Naxxanar Skeletal Mage'),
(25432, 0, 0, '%s goes into a frenzy!', 16, 0, 100, 0, 0, 0, 'Mate of Magmothregar'),
(25804, 0, 0, 'You seek to deafen me? Pathetic... Wait... What''s that sound?', 12, 0, 100, 0, 0, 0, 'Harold Lane'),
(25806, 0, 0, 'Now THIS is a sport!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 1, 'KILL KILL KILL!!!!!!!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 2, 'I''m sure ol'' Hemet can do something with your bones!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 3, 'Give it up, little beast!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 4, 'Just fifty more hooves and I''ll have the new gun!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 5, 'No way! Rhino head helmet for the low, low price of thirty rhino heads? I''ll take two at those prices!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 6, 'I wonder what Nesingwary will give me for your hide!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 7, 'It''s gonna be veal tonight!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher'),
(25806, 0, 8, 'Nesingwary is going to go broke if he keeps this up! Lane probably has no idea what he''s doing!', 12, 0, 100, 0, 0, 0, 'Loot Crazed Poacher');
