-- Borean Tundra: combat SmartAI for 41 creatures that cast no spell here and had no AI.
-- Rows from 5.4.8 (Legends of Azeroth), taken only where every event, action and target type is numbered the same in this core,
-- every spell is in the client data and 3.3.5 casts at least half of the same spells. Quest, summon and waypoint scripts are not included.
UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE `entry` IN (24469,24563,24566,24770,25203,25204,25215,25217,25350,25396,25432,25448,25452,25470,25585,25601,25611,25650,25654,25700,25707,25712,25713,25715,25716,25721,25728,25752,25753,25758,25792,25793,25804,25806,25836,25839,25843,25880,26126,26157,27860) AND `ScriptName` = '';
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND `entryorguid` IN (24469,24563,24566,24770,25203,25204,25215,25217,25350,25396,25432,25448,25452,25470,25585,25601,25611,25650,25654,25700,25707,25712,25713,25715,25716,25721,25728,25752,25753,25758,25792,25793,25804,25806,25836,25839,25843,25880,26126,26157,27860);
DELETE FROM `creature_text` WHERE `entry` IN (25396,25432,25804,25806);
